import{_ as i,B as n,o as s,c as l,a8 as d,a as t,E as r,f as o}from"./chunks/framework.CNIpabDg.js";const b=JSON.parse(`{"title":"Text Editor (executable)","description":"Understand how Xila's WebAssembly Text Editor edits large UTF-8 files with bounded memory.","frontmatter":{"layout":"doc","docType":"explanation","description":"Understand how Xila's WebAssembly Text Editor edits large UTF-8 files with bounded memory."},"headers":[],"relativePath":"explanation/architecture/executables/text_editor.md","filePath":"explanation/architecture/executables/text_editor.md","lastUpdated":1793145952000}`),c={name:"explanation/architecture/executables/text_editor.md"};function p(u,e,h,g,m,f){const a=n("CodeReference");return s(),l("div",{"data-pagefind-body":!0,"data-pagefind-meta":"date:1793145952000"},[e[6]||(e[6]=d('<h1 id="text-editor-executable" tabindex="-1">Text Editor (executable) <a class="header-anchor" href="#text-editor-executable" aria-label="Permalink to &quot;Text Editor (executable)&quot;">​</a></h1><p>Text Editor is a bundled <code>wasm32-wasip1</code> application. It creates and edits UTF-8 files through the Xila VFS without retaining the whole document in guest memory.</p><h2 id="editing-model" tabindex="-1">Editing model <a class="header-anchor" href="#editing-model" aria-label="Permalink to &quot;Editing model&quot;">​</a></h2><p>The application displays one <strong>4 KiB, UTF-8-safe page</strong> at a time. Enter an absolute file path, choose <strong>New</strong> or <strong>Open</strong>, then navigate using <strong>Previous</strong> and <strong>Next</strong>. <strong>Save</strong> writes the edited document to the selected path.</p><p>Instead of reading the whole file into RAM, the editor works on a temporary on-disk copy and uses fixed-size I/O buffers. A file can be larger than a page without requiring memory proportional to its size.</p><h2 id="storage-and-failure-boundaries" tabindex="-1">Storage and failure boundaries <a class="header-anchor" href="#storage-and-failure-boundaries" aria-label="Permalink to &quot;Storage and failure boundaries&quot;">​</a></h2><ul><li>The parent directory must be writable, with approximately enough free space to hold a second copy of the file.</li><li>Invalid UTF-8 and NUL bytes are rejected; this is a text editor, not a binary editor.</li><li>Saving streams the working copy to the target file.</li><li>A failed save retains the temporary working copy so the user can retry.</li><li>Normal closure cleans up the temporary copy through WASI file unlink support.</li></ul><p>The editor is included in the prebuilt guest bundle for <strong>new</strong> native and browser disk images. Existing persistent disks do not automatically receive new guest binaries.</p><h2 id="working-copy-lifecycle-and-memory-costs" tabindex="-1">Working-copy lifecycle and memory costs <a class="header-anchor" href="#working-copy-lifecycle-and-memory-costs" aria-label="Permalink to &quot;Working-copy lifecycle and memory costs&quot;">​</a></h2><p>The editor separates <code>interface.rs</code> (LVGL guest events) from <code>storage.rs</code> (<code>WorkingCopy</code>). Opening a document creates a unique hidden working file in the <strong>same parent directory</strong> as the selected source. Files are copied in <strong>4 KiB chunks</strong>, validating UTF-8 and rejecting embedded NUL bytes. New documents receive an initially empty working copy.</p><p><code>WorkingCopy::read_page(offset, &amp;mut [u8; 4096])</code> accepts only UTF-8 boundaries, returns a page length ending on a valid codepoint, and never needs to load the whole document. <code>replace_page</code> edits the on-disk working file while shifting the remaining tail in bounded chunks. The UI retains just the visible text and status, not the complete source file.</p><p>Unique temporary file creation tries up to <strong>32</strong> timestamp/sequence candidates. The working copy is removed by its <code>Drop</code> implementation when normal cleanup runs; an abnormal guest termination can leave temporary files behind. The parent directory needs enough free storage for the copy and appropriate create/write permissions.</p><h2 id="save-and-failure-recovery" tabindex="-1">Save and failure recovery <a class="header-anchor" href="#save-and-failure-recovery" aria-label="Permalink to &quot;Save and failure recovery&quot;">​</a></h2><p>The UI polls a bounded batch of up to <strong>32</strong> graphics events per turn with a <strong>16 ms</strong> sleep. The open/new action and close requests require a second confirmation to discard unsaved edits. Current page changes are committed to the working copy before navigation and save.</p><p><code>WorkingCopy::save_to(target)</code> streams the working data back to the selected path. <strong>It does not atomically replace the destination</strong>; a failed write can truncate or partially overwrite the original. Keeping the working copy lets the user retry, but it cannot automatically recover a previously overwritten destination after crash/power loss.</p><p>The path field has a <strong>240-character</strong> UI limit, distinct from the 4096-byte editing page. The default path is <code>/configuration/shared/text_editor/untitled.txt</code>. The working-copy strategy gives roughly constant guest memory use at the cost of extra disk I/O and temporary storage.</p><h3 id="source-references" tabindex="-1">Source references <a class="header-anchor" href="#source-references" aria-label="Permalink to &quot;Source references&quot;">​</a></h3>',17)),t("ul",null,[t("li",null,[r(a,{repo:"applications",path:"executables/text_editor/src/storage.rs"}),e[0]||(e[0]=o(" — WorkingCopy, UTF-8 paging, save and Drop.",-1))]),t("li",null,[r(a,{repo:"applications",path:"executables/text_editor/src/interface.rs"}),e[1]||(e[1]=o(" — actions, input length and event loop.",-1))]),t("li",null,[r(a,{repo:"applications",path:"executables/text_editor/src/main.rs"}),e[2]||(e[2]=o(" — installer and guest startup.",-1))]),e[3]||(e[3]=t("li",null,[t("a",{href:"/explanation/architecture/subsystems/virtual_file_system.html"},"VFS subsystem"),o(" — backing file ownership.")],-1))]),e[7]||(e[7]=t("h2",{id:"references",tabindex:"-1"},[o("References "),t("a",{class:"header-anchor",href:"#references","aria-label":'Permalink to "References"'},"​")],-1)),t("ul",null,[t("li",null,[r(a,{repo:"applications",path:"executables/text_editor/README.md"})]),t("li",null,[r(a,{repo:"applications",path:"executables/text_editor"})]),e[4]||(e[4]=t("li",null,[t("a",{href:"/reference/wasm-runtime.html"},"WASM runtime")],-1)),e[5]||(e[5]=t("li",null,[t("a",{href:"/explanation/browser-storage.html"},"Browser storage")],-1))])])}const x=i(c,[["render",p]]);export{b as __pageData,x as default};
